// modules/library/pages/AuthorList.js
import { useEffect, useState } from "react";
import { authorApi } from "../api/authorApi";

export default function AuthorList() {
  const [authors, setAuthors] = useState([]);

  useEffect(() => {
    authorApi.get("/").then((res) => setAuthors(res.data));
  }, []);

  const deleteAuthor = async (id) => {
    if (!window.confirm("Remove this author?")) return;

    await authorApi.delete(`/${id}`);
    setAuthors(authors.filter((a) => a.author_id !== id));
  };

  return (
    <div className="content-header p-4">
      <h2>Authors</h2>

      <a className="btn btn-primary mb-3" href="/library/author/create">
        + Add Author
      </a>

      <table className="table table-bordered table-hover">
        <thead>
          <tr>
            <th>#</th>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Nationality</th>
            <th>Date of Birth</th>
            <th>Website</th>
            <th>Actions</th>
          </tr>
        </thead>

        <tbody>
          {authors.length ? (
            authors.map((a, i) => (
              <tr key={a.author_id}>
                <td>{i + 1}</td>
                <td>{a.first_name}</td>
                <td>{a.last_name}</td>
                <td>{a.nationality || "-"}</td>
                <td>{a.date_of_birth || "-"}</td>
                <td>
                  {a.website ? (
                    <a href={a.website} target="_blank" rel="noreferrer">
                      {a.website}
                    </a>
                  ) : (
                    "-"
                  )}
                </td>
                <td>
                  <a
                    className="btn btn-info btn-sm"
                    href={`/library/author/edit/${a.author_id}`}
                  >
                    Edit
                  </a>
                  <button
                    className="btn btn-danger btn-sm ms-2"
                    onClick={() => deleteAuthor(a.author_id)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan={7} className="text-center text-muted">
                No authors available.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
